CBomb::CBomb (f32 damage, ISceneNode *rootobj)
{
	m_sceneroot = rootobj;
	ISceneNode* model_root = LoadColladaScene("Scenes/Goblin_bomb/bomb.bdae", true);
	cleanNode(model_root, false);
	m_sceneroot? m_sceneroot->addChild( model_root ) : __IRR_SCENE()->getRootSceneNode()->addChild( model_root );
	setRoot( model_root );
	model_root->setRotation(quaternion(0, PI, 0));

	setAnim(0, true);

	m_free = false;

	m_dead = false;

	m_touch.m_zLevel = 0;
	m_touch.SetEnabled(false);

	m_time = 0.0f;

	m_velocity = v3f(0.0f, 0.0f, 0.0f);

	m_damage = damage;

	m_isForHelpMenu = false;

	//little hardoced, when units are created for the menu, they have always rootobj
	if ( m_sceneroot ) 
		m_isForHelpMenu = true;
}

CBomb::~CBomb ()
{
	if ( getRoot() )
	{	
		getRoot()->remove();
		getRoot()->drop();
	}
}

void FireballExplosion (v3f position, float radius, float maxDamage, float elfSurvivalChance, int* unitsHitByKind, int* curBounceUnitsHit, float scale = 1.0f);

void CBomb::update (f32 time)
{
	p2i pos = screenFrom3DPos(getRoot()->getAbsolutePosition());
	m_touch.SetScreenCoordinates(pos.X - 20, pos.Y - 20, 40, 40);

	if (checkEvent("anim_end") && strcmp(getCurrentAnimName(), "explode") == 0)
	{
		explode(false);
	}

	if (m_time > 0.0f && strcmp(getCurrentAnimName(), "pulse") == 0)
	{
		m_time -= time;
		if (m_time <= 0.0f)
		{
			explodeLater();
		}
	}

	if (m_touch.IsActive())
	{
		// drag around
		position2di touch;
		m_touch.GetTouchPos_Current(touch.X, touch.Y);
		plane3df targetPlane = CPlayfield::GetInstance()->getFlyingPlane();
		line3df ray = __IRR_SCENE()->getSceneCollisionManager()->getRayFromScreenCoordinates(touch);
		vector3df targetPos;
		targetPlane.getIntersectionWithLine(ray.start, ray.getVector(), targetPos);

		v3f targetDir = (targetPos - getRoot()->getPosition()) / time;
		float maxVelocity = 25.0f;
		if (targetDir.getLength() > maxVelocity)
			targetDir.setLength(maxVelocity);

		m_velocity = targetDir;
	}
	else
	{
		m_velocity += v3f(0, -9.8f * 4.0f * 0.9f, 0) * time;
	}

	if (getCurrentAnimIndex() != 0)
	{
		if( (CPlayfield::GetInstance()->getGroundPlane().classifyPointRelation(getRoot()->getPosition()) == ISREL3D_FRONT) )
		{			
			getRoot()->setPosition(getRoot()->getPosition() + m_velocity * time);

			if( (CPlayfield::GetInstance()->getGroundPlane().classifyPointRelation(getRoot()->getPosition()) == ISREL3D_FRONT) )				
			{
				getRoot()->setPosition(getRoot()->getPosition() + m_velocity * time);

				if( (CPlayfield::GetInstance()->getGroundPlane().classifyPointRelation(getRoot()->getPosition()) != ISREL3D_FRONT) )
				{
					__MGR_SOUNDS()->play( SFX_ATTACK_DROP_BOMB_IMPACT );
				}

				getRoot()->setPosition(getRoot()->getPosition() - m_velocity * time);
			}

			getRoot()->setPosition(getRoot()->getPosition() - m_velocity * time);
		}

		getRoot()->setPosition(getRoot()->getPosition() + m_velocity * time);

		if (CPlayfield::GetInstance()->getGroundPlane().classifyPointRelation(getRoot()->getPosition()) != ISREL3D_FRONT)
		{
			v3f pos;
			CPlayfield::GetInstance()->getGroundPlane().getIntersectionWithLine(getRoot()->getPosition(), m_velocity, pos);
			getRoot()->setPosition(pos);
			m_velocity.Y = -m_velocity.Y;
			m_velocity *= 0.5f;
		}
		if (CPlayfield::GetInstance()->getCastlePlane().classifyPointRelation(getRoot()->getPosition()) != ISREL3D_FRONT)
		{
			v3f pos;
			CPlayfield::GetInstance()->getCastlePlane().getIntersectionWithLine(getRoot()->getPosition(), m_velocity, pos);
			getRoot()->setPosition(pos);
			m_velocity.X = -m_velocity.X;
			m_velocity *= 0.5f;
		}
	}

	updateAtEndOfFrame(time);
}

